window.AUTH=window.AUTH||{};window.AUTH["89-1027"]={"d":"89-1027","id":"1990/89-1027","n":"Norfolk & Western Railway Company v. American Train Dispatchers Association","src":["osg"],"briefs":[{"k":"reply","label":"Reply brief for the federal respondents supporting petitioners","date":"","url":"https://www.justice.gov/osg/media/231641/dl?inline","side":"pet","src":"osg","fmt":"Text","detail":"https://www.justice.gov/osg/brief/norfolk-and-western-railway-company-et-al-petitioners-v-american-train-dispatchers-1","toa":false,"n":22},{"k":"respondent","label":"Brief for the federal respondents supporting petitioners","date":"","url":"https://www.justice.gov/osg/media/210601/dl?inline","side":"res","src":"osg","fmt":"Text","detail":"https://www.justice.gov/osg/brief/norfolk-and-western-railway-company-et-al-petitioners-v-american-train-dispatchers-0","toa":false,"n":59}],"opinion":"https://tile.loc.gov/storage-services/service/ll/usrep/usrep499/usrep499117/usrep499117.pdf","tr":false,"items":[{"t":"case","label":"Schwabacher v. United States","cite":"334 U.S. 182","y":1948,"id":"scdb/1947-079","sc":1,"op":5,"sum":"The Commission was not free to renounce or delegate its power to settle finally the amount of capital liabilities of the new company and the proportion or amount thereof which each class of stockholders should receive on account of its contributions to the new entity.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"","1":""}},{"t":"case","label":"Illinois v. City of Milwaukee","cite":"406 U.S. 91","y":1972,"id":"1971/49_orig","sc":1,"sum":"The State of Illinois has filed a motion for leave to file a bill of' complaint against' four Wisconsin cities and two local sewerage commissions for allegedly polluting Lake Michigan. Illinois seeks to invoke the Court's original jurisdiction on the ground that the defendants are instrumentalities of Wisconsin and that this suit is therefore one against the State that must be brought in this Court under Art. III, § …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Warren v. United States","cite":"340 U.S. 523","y":1951,"id":"scdb/1950-043","sc":1,"sum":"Petitioner was entitled to recover from the United States for maintenance and cure.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Erie R.R. v. Tompkins","cite":"304 U.S. 64","y":1938,"id":"1900-1940/304us64","sc":1,"sum":"A case in which the Court overturned its prior decision in Swift v. Tyson and held that federal courts exercising diversity jurisdiction cannot create their own common law for issues that properly fall within state law.","sumSrc":"Oyez","by":{"0":"","1":""}},{"t":"case","label":"ICC v. Brotherhood of Locomotive Engineers","cite":"482 U.S. 270","y":1987,"id":"1986/85-792","sc":1,"op":3,"sum":"In October 1982, petitioner Interstate Commerce Commission (ICC or Commission) issued an order, which, inter alia, granted petitioner Missouri-Kansas-Texas Railroad Co. and another railroad the right to conduct operations using the tracks of a third, newly consolidated carrier. In April 1983, respondent Brotherhood of Locomotive Engineers (BLE) filed a \"Petition for Clarification\" asking the ICC to declare that the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"","1":""}},{"t":"case","label":"United States v. Lowden","cite":"308 U.S. 225","y":1939,"id":"scdb/1939-002","sc":1,"op":2,"sum":"Section 5 (4) (b) of the Interstate Commerce Act provides that the Commission may authorize carriers to consolidate or lease their properties where it finds that that action, subject to such conditions and modifications as it shall find to be just and reasonable, will be in harmony with and in furtherance of the plan of consolidation of railway properties established pursuant to paragraph (3) of that section and …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"","1":""}},{"t":"case","label":"Railway Labor Executives' Ass'n v. United States","cite":"339 U.S. 142","y":1950,"id":"scdb/1949-055","sc":1,"sum":"Neither such discrimination nor such insubstantial \"protection\" is consistent with the purpose and history of § 5 (2) (f) of the Interstate Commerce Act.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"","1":""}},{"t":"case","label":"Brotherhood of Locomotive Engineers v. Chicago & N.W. Ry.","cite":"314 F.2d 424","y":1963,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/314/424/","op":1,"by":{"0":"","1":""}},{"t":"case","label":"International Brotherhood of Electrical Workers v. ICC","cite":"862 F.2d 330","y":1988,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/862/330/","by":{"0":""}},{"t":"case","label":"United Transp. Union v. United States","cite":"905 F.2d 463","y":1990,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/905/463/","by":{"0":""}},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1983,"id":"1983/82-472","sc":1,"sum":"The insurance proceeds petitioner received as a result of his arson activities constitute an \"interest\" within the meaning of § 1963(a)(1) and are therefore subject to forfeiture.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"","1":""}},{"t":"case","label":"INS v. Cardoza-Fonseca","cite":"480 U.S. 421","y":1978,"id":"1986/85-782","sc":1,"sum":"The §243(h) \"clear probability\" standard of proof does not govern asylum applications under §208(a).","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"","1":""}},{"t":"case","label":"Brotherhood of Maintenance of Way Employees v. United States","cite":"366 U.S. 169","y":1961,"id":"1960/681","sc":1,"sum":"This does not require that all employees remain in the employ of the surviving railroad for at least the length of their previous employment up to four years; it is satisfied by a requirement that discharged employees receive adequate compensation benefits. Pp. 169-179. 189 F. Supp. 942, affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"","1":""}},{"t":"case","label":"Wilson v. New","cite":"243 U.S. 332","y":1917,"id":"scdb/1916-143","sc":1,"sum":"The effect of the Act of September 3, 5, 1916, entitled “An Act to establish an eight-hour day for employees of carriers engaged in interstate and foreign commerce, and for other purposes,” c. 436, 39 Stat. 721, is not only to establish permanently an eight-hour standard for work and wages as between the carriers and employees affected, but also to fix a scale of minimum wages, to wit, the rate of wages then …","sumSrc":"Headnote (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Louisville & Nashville R.R. v. Mottley","cite":"219 U.S. 467","y":1911,"id":"scdb/1910-078","sc":1,"sum":"The intent of Congress is to be gathered from the words of the act according to their ordinary acceptation, and the act should be con-, ¿trued in the light of circumstances existing at the timte it was passed. Personal hardships cannot be considered; nor can the court mold the. statute to meet its views of.jbstice in a particular case.","sumSrc":"Headnote (U.S. Reports)","by":{"0":""}},{"t":"case","label":"NLRB v. Curtin Matheson Scientific, Inc.","cite":"110 S. Ct. 1542","y":1990,"url":"https://www.courtlistener.com/c/S.%20Ct./110/1542/","sc":1,"by":{"0":""}},{"t":"case","label":"NLRB v. J. Weingarten","cite":"420 U.S. 251","y":1975,"id":"1974/73-1363","sc":1,"sum":"The employer violated § 8 (a) (1) of the National Labor Relations Act because it interfered with, restrained, and coerced the individual right of an employee, protected by § 7, \"to engage in... concerted activities for... mutual aid or protection... Y' when it denied the employee's request for the presence of her union representative at the investigatory interview that the employee reasonably believed would result …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"usc","label":"49 U.S.C. § 11341","url":"https://www.law.cornell.edu/uscode/text/49/11341","subs":["(a)"],"stext":{"head":"§11341. Scope of authority","paras":[[0,"(a) The authority of the Interstate Commerce Commission under this subchapter is exclusive. A carrier or corporation participating in or resulting from a transaction approved by or exempted by the Commission under this subchapter may carry out the transaction, own and operate property, and exercise control or franchises acquired through the transaction without the approval of a State authority. A carrier, corporation, or person participating in that approved or exempted transaction is exempt from the antitrust laws and from all other law, including State and municipal law, as necessary to let that person carry out the transaction, hold, maintain, and operate property, and exercise control or franchises acquired through the transaction. However, if a purchase and sale, a lease, or a corporate consolidation or merger is involved in the transaction, the carrier or corporation may carry out the transaction only with the assent of a majority, or the number required under applicable State law, of the votes of the holders of the capital stock of that corporation entitled to vote. The vote must occur at a regular meeting, or special meeting called for that purpose, of those stockholders and the notice of the meeting must indicate its purpose."],[0,"(b) A power granted under this subchapter to a carrier or corporation is in addition to and changes its powers under its corporate charter and under State law. Action under this subchapter does not establish or provide for establishing a corporation under the laws of the United States."]],"more":false,"ed":"1994","src":"https://www.govinfo.gov/link/uscode/49/11341?type=usc&year=mostrecent&link-type=html"},"op":6,"head":"§11341. Scope of authority","tname":"Transportation","by":{"0":"","1":""}},{"t":"usc","label":"49 U.S.C. § 10101a","url":"https://www.law.cornell.edu/uscode/text/49/10101a","by":{"0":""}},{"t":"usc","label":"49 U.S.C. § 11344","url":"https://www.law.cornell.edu/uscode/text/49/11344","subs":["(c)"],"stext":{"head":"§11344. Consolidation, merger, and acquisition of control: general procedure and conditions of approval","paras":[[0,"(a) The Interstate Commerce Commission may begin a proceeding to approve and authorize a transaction referred to in section 11343 of this title on application of the person seeking that authority. When an application is filed with the Commission, the Commission shall notify the chief executive officer of each State in which property of the carriers involved in the proposed transaction is located and shall notify those carriers. If a motor carrier providing transportation subject to the jurisdiction of the Commission under subchapter II of chapter 105 of this title is involved in the transaction, the Commission must notify the persons specified in section 10328(b) of this title. The Commission shall hold a public hearing when a rail carrier providing transportation subject to the jurisdiction of the Commission under subchapter I of that chapter is involved in the transaction unless the Commission determines that a public hearing is not necessary in the public interest."],[0,"(b)(1) In a proceeding under this section which involves the merger or control of at least two class I railroads, as defined by the Commission, the Commission shall consider at least the following:"],[1,"(A) the effect of the proposed transaction on the adequacy of transportation to the public."],[1,"(B) the effect on the public interest of including, or failing to include, other rail carriers in the area involved in the proposed transaction."],[1,"(C) the total fixed charges that result from the proposed transaction."],[1,"(D) the interest of carrier employees affected by the proposed transaction."],[1,"(E) whether the proposed transaction would have an adverse effect on competition among rail carriers in the affected region."],[0,"(2) In a proceeding under this section which involves only carriers of passengers providing transportation subject to the jurisdiction of the Interstate Commerce Commission under subchapter II of chapter 105 of this title, the Commission shall consider at least the following:"],[1,"(A) the effect of the proposed transaction on the adequacy of transportation to the public."],[1,"(B) the effect on the public interest of including, or failing to include, other rail carriers in the area involved in the proposed transaction."],[1,"(C) the total fixed charges that result from the proposed transaction."],[1,"(D) the interest of carrier employees affected by the proposed transaction."],[0,"(c) The Commission shall approve and authorize a transaction under this section when it finds the transaction is consistent with the public interest. The Commission may impose conditions governing the transaction. When the transaction contemplates a guaranty or assumption of payment of dividends or of fixed charges or will result in an increase of total fixed charges, the Commission may approve and authorize the transaction only if it finds that the guaranty, assumption, or increase is consistent with the public interest. When a rail carrier, or a person controlled by or affiliated with a rail carrier, is an applicant and the transaction involves a motor carrier, the Commission may approve and authorize the transaction only if it finds that the transaction is consistent with the public interest, will enable the rail carrier to use motor carrier transportation to public advantage in its operations, and will not unreasonably restrain competition. When a rail carrier is involved in the transaction, the Commission may require inclusion of other rail carriers located in the area involved in the transaction if they apply for inclusion and the Commission finds their inclusion to be consistent with the public interest."],[0,"(d) In a proceeding under this section which does not involve the merger or control of at least two class I railroads, as defined by the Commission, the Commission shall approve such an application unless it finds that—"],[1,"(1) as a result of the transaction, there is likely to be substantial lessening of competition, creation of a monopoly, or restraint of trade in freight surface transportation in any region of the United States; and"],[1,"(2) the anticompetitive effects of the transaction outweigh the public interest in meeting significant transportation needs."],[0,"In making such findings, the Commission shall, with respect to any application that is part of a plan or proposal developed under section 333(a)–(d) of this title, accord substantial weight to any recommendations of the Secretary of Transportation. The provisions of this subsection do not apply to any proceeding under this section which involves only carriers of passengers providing transportation subject to the jurisdiction of the Commission under subchapter II of chapter 105 of this title."],[0,"(e) A rail carrier, or a person controlled by or affiliated with a rail carrier, together with one or more affected shippers, may apply for approval under this subsection of a transaction for the purpose of providing motor carrier transportation prior or subsequent to rail transportation to serve inadequately served shippers located on a railroad other than the applicant carrier. Such application shall be approved by the Commission if the applicants demonstrate presently impaired rail service and inadequate motor common carrier service which results in the serious failure of the rail carrier serving the shippers to meet the rail equipment or transportation schedules of shippers or seriously to fail otherwise to provide adequate normal rail services required by shippers and which shippers would reasonably expect the rail carrier to provide. The Commission shall approve or disapprove applications under this subsection within 30 days after receipt of such application. The Commission shall approve applications which are not protested by interested parties within 30 days following receipt of such application."]],"more":false,"ed":"1994","src":"https://www.govinfo.gov/link/uscode/49/11344?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§11344. Consolidation, merger, and acquisition of control: general procedure and conditions of approval","tname":"Transportation","by":{"0":"","1":""}},{"t":"usc","label":"49 U.S.C. § 11347","url":"https://www.law.cornell.edu/uscode/text/49/11347","stext":{"head":"§11347. Employee protective arrangements in transactions involving rail carriers","paras":[[0,"When a rail carrier is involved in a transaction for which approval is sought under sections 11344 and 11345 or section 11346 of this title, the Interstate Commerce Commission shall require the carrier to provide a fair arrangement at least as protective of the interests of employees who are affected by the transaction as the terms imposed under this section before February 5, 1976, and the terms established under sections 24307(c), 24312, and 24706(c) of this title. Notwithstanding this subtitle, the arrangement may be made by the rail carrier and the authorized representative of its employees. The arrangement and the order approving the transaction must require that the employees of the affected rail carrier will not be in a worse position related to their employment as a result of the transaction during the 4 years following the effective date of the final action of the Commission (or if an employee was employed for a lesser period of time by the carrier before the action became effective, for that lesser period)."]],"more":false,"ed":"1994","src":"https://www.govinfo.gov/link/uscode/49/11347?type=usc&year=mostrecent&link-type=html"},"op":9,"head":"§11347. Employee protective arrangements in transactions involving rail carriers","tname":"Transportation","by":{"0":"","1":""}},{"t":"usc","label":"45 U.S.C. § 151","url":"https://www.law.cornell.edu/uscode/text/45/151","stext":{"head":"§151. Definitions; short title","paras":[[0,"When used in this chapter and for the purposes of this chapter—"],[0,"First. The term \"carrier\" includes any railroad subject to the jurisdiction of the Surface Transportation Board, any express company that would have been subject to subtitle IV of title 49, as of December 31, 1995,,1 and any company which is directly or indirectly owned or controlled by or under common control with any carrier by railroad and which operates any equipment or facilities or performs any service (other than trucking service) in connection with the transportation, receipt, delivery, elevation, transfer in transit, refrigeration or icing, storage, and handling of property transported by railroad, and any receiver, trustee, or other individual or body, judicial or otherwise, when in the possession of the business of any such \"carrier\": Provided, however, That the term \"carrier\" shall not include any street, interurban, or suburban electric railway, unless such railway is operating as a part of a general steam-railroad system of transportation, but shall not exclude any part of the general steam-railroad system of transportation now or hereafter operated by any other motive power. The Surface Transportation Board is authorized and directed upon request of the Mediation Board or upon complaint of any party interested to determine after hearing whether any line operated by electric power falls within the terms of this proviso. The term \"carrier\" shall not include any company by reason of its being engaged in the mining of coal, the supplying of coal to a carrier where delivery is not beyond the mine tipple, and the operation of equipment or facilities therefor, or in any of such activities."],[0,"Second. The term \"Adjustment Board\" means the National Railroad Adjustment Board created by this chapter."],[0,"Third. The term \"Mediation Board\" means the National Mediation Board created by this chapter."],[0,"Fourth. The term \"commerce\" means commerce among the several States or between any State, Territory, or the District of Columbia and any foreign nation, or between any Territory or the District of Columbia and any State, or between any Territory and any other Territory, or between any Territory and the District of Columbia, or within any Territory or the District of Columbia, or between points in the same State but through any other State or any Territory or the District of Columbia or any foreign nation."],[0,"Fifth. The term \"employee\" as used herein includes every person in the service of a carrier (subject to its continuing authority to supervise and direct the manner of rendition of his service) who performs any work defined as that of an employee or subordinate official in the orders of the Surface Transportation Board now in effect, and as the same may be amended or interpreted by orders hereafter entered by the Board pursuant to the authority which is conferred upon it to enter orders amending or interpreting such existing orders: Provided, however, That no occupational classification made by order of the Surface Transportation Board shall be construed to define the crafts according to which railway employees may be organized by their voluntary action, nor shall the jurisdiction or powers of such employee organizations be regarded as in any way limited or defined by the provisions of this chapter or by the orders of the Board."],[0,"The term \"employee\" shall not include any individual while such individual is engaged in the physical operations consisting of the mining of coal, the preparation of coal, the handling (other than movement by rail with standard railroad locomotives) of coal not beyond the mine tipple, or the loading of coal at the tipple."],[0,"Sixth. The term \"representative\" means any person or persons, labor union, organization, or corporation designated either by a carrier or group of carriers or by its or their employees, to act for it or them."],[0,"Seventh. The term \"district court\" includes the United States District Court for the District of Columbia; and the term \"court of appeals\" includes the United States Court of Appeals for the District of Columbia."],[0,"This chapter may be cited as the \"Railway Labor Act.\""]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/45/151?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§151. Definitions; short title","tname":"Railroads","by":{"0":"","1":""}},{"t":"case","label":"New York Dock Ry. v. United States","cite":"609 F.2d 83","y":1979,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/609/83/","op":17,"by":{"1":""}},{"t":"case","label":"RLA. See Consolidated Rail Corp. v. Railway Labor Executives' Ass'n","cite":"109 S. Ct. 2477","y":1989,"url":"https://www.courtlistener.com/c/S.%20Ct./109/2477/","sc":1,"by":{"1":""}},{"t":"case","label":"Emergency Board. Detroit & Toledo Shore Line R.R. v. United Transp. Union","cite":"396 U.S. 142","y":1969,"id":"1969/29","sc":1,"op":2,"sum":"The status quo that is to be maintained pursuant to § 6 of the Railway Labor Act while the procedures of the Act are being exhausted consists of the actual, objective working conditions out of which the dispute arose, whether or not those conditions are covered in an existing collective-bargaining agreement. Order of Conductors v. Pitney, 326 U. S. 561, and Williams v. Terminal Co., 315 U. S. 386, distinguished. Pp. …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":""}},{"t":"case","label":"Burlington Northern R.R. v. Brotherhood of Maintenance of Way Employees","cite":"481 U.S. 429","id":"1986/86-39","sc":1,"op":1,"sum":"The Court held that Congress passed the Norris-LaGuardia Act expressly to prevent courts from distinguishing between primary and secondary actors for the purposes of labor immunity in labor disputes.","sumSrc":"Oyez","by":{"1":""}},{"t":"case","label":"United States v. Riverside Bayview Homes, Inc.","cite":"474 U.S. 121","y":1985,"id":"1985/84-701","sc":1,"sum":"The Clean Water Act prohibits any discharge of dredged or fill materials into \"navigable waters\"-defined as the \"waters of the United States\"unless authorized by a permit issued by the Army Corps of Engineers (Corps). Construing the Act to cover all \"freshwater wetlands\" that are adjacent to other covered waters, the Corps issued a regulation defining such wetlands as \"those areas that are inundated or saturated by …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":""}},{"t":"case","label":"Chevron U.S.A. Inc. v. Natural Resources Defense Council, Inc.","cite":"467 U.S. 837","y":1984,"id":"1983/82-1005","sc":1,"op":2,"sum":"The Supreme Court held that the bubble regulation was a reasonable interpretation of the term “stationary source” in the Clean Air Act. Congress did not have a specific intention for the interpretation of that term, and the EPA’s regulation was a reasonable policy choice. The regulation also provided reasonable accommodations for the many competing interests affected by the Act.","sumSrc":"Oyez","by":{"1":""}},{"t":"case","label":"Consumer Prod. Safety Comm'n v. GTE Sylvania, Inc.","cite":"447 U.S. 102","y":1980,"id":"1979/79-521","sc":1,"sum":"Section 6 (b) (1) governs the disclosure of records by the Commission pursuant to a request under the FOIA.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":""}},{"t":"case","label":"Aaron v. SEC.","cite":"446 U.S. 680","y":1980,"id":"1979/79-66","sc":1,"sum":"The Court held that plain language and the legislative history of the statutes required the SEC to establish defendant’s intent to “deceive, manipulate, or defraud” for violations of Section 10(b) and the part of Section 17(a) that specifically refers to the use of a device, scheme, or artifice with intent to defraud.","sumSrc":"Oyez","by":{"1":""}},{"t":"case","label":"Greyhound Corp. v. Mt. Hood Stages, Inc.","cite":"437 U.S. 322","y":1978,"id":"1977/77-598","sc":1,"sum":"The Clayton Act's statute of limitations was GREYHOUND CORP. v. MT. HOOD STAGES, INC. not tolled under § 5 (i) by the filing of the Government's petition to intervene in the ICC proceeding.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":""}},{"t":"case","label":"Hendrickson v. Apperson","cite":"245 U.S. 105","y":1917,"id":"scdb/1917-043","sc":1,"sum":"A valid judgment was recovered against Taylor County, Kentucky, upon bonds which it had issued under a refunding act. 1 Acts Ky., 1877-78, p. 554. Under the law existing when the bonds were issued (Ky. Stats., 1894, §4131), as construed by the highest court of the State, it was the duty of the county court when the office of sheriff was vacant to appoint a single collector, under a single bond, to collect all county …","sumSrc":"Headnote (U.S. Reports)","by":{"1":""}},{"t":"case","label":"Farmers & Merchants Bank v. Federal Reserve Bank","cite":"262 U.S. 649","y":1923,"id":"scdb/1922-222","sc":1,"op":1,"sum":"1. Many state banks, in satisfying cheeks drawn upon them by their depositors and sent through other banks for collection, were accustomed to remit by draft on their reserves elsewhere and to make a small charge, called exchange, deducted from the remittance. The Federal Reserve Board, and the federal reserve banks, being forbidden to pay exchange charges, but believing it their duty to accept checks on any bank for …","sumSrc":"Headnote (U.S. Reports)","by":{"1":""}},{"t":"case","label":"Int'l Brotherhood of Teamsters v. Oliver","cite":"358 U.S. 283","y":1959,"id":"1958/49","sc":1,"sum":"Since that provision was part of an agreement resulting from the exercise of collective bargaining rights under the National Labor Relations Act, the state court was precluded from applying the state antitrust law to prohibit the parties from carrying out its terms. Pp. 284-297. (1) In the light of its history and its purpose to protect the negotiated wage scale against evasion through payment to ownerdrivers of …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":""}},{"t":"case","label":"Slocum v. Delaware, L. & W. R.R.","cite":"339 U.S. 239","y":1950,"id":"scdb/1949-060","sc":1,"op":1,"sum":"Under § 3 of the Railway Labor Act, the jurisdiction of the Adjustment Board to adjust grievances and disputes of the type here involved is exclusive, and the state court erred in interpreting the agreements and entering a declaratory judgment.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":""}},{"t":"case","label":"Railway Employees' Dep't v. Hanson","cite":"351 U.S. 225","y":1956,"id":"1955/451","sc":1,"sum":"Claiming that a \"union shop\" agreement between an interstate railroad and unions of its employees made pursuant to § 2, Eleventh, of the Railway Labor Act, which expressly authorizes such agreements notwithstanding any state law, violated the First and Fifth Amendments of the Federal Constitution and the \"right to work\" provision of the Nebraska Constitution, nonunion employees of the railroad sued in a Nebraska …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":""}},{"t":"case","label":"California v. Taylor","cite":"353 U.S. 553","y":1957,"id":"1956/385","sc":1,"sum":"The Railway Labor Act applies to the State Belt Railroad, a common carrier owned and operated by the State of California and engaged in interstate commerce; and, notwithstanding the fact that the Railroad's employees are state employees appointed under the state civil service laws, the National Railroad Adjustment Board has jurisdiction over claims based on a collective-bargaining agreement between the Railroad and …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":""}},{"t":"case","label":"Brotherhood of Locomotive Eng'rs v. Boston & Maine Corp.","cite":"788 F.2d 794","url":"https://www.courtlistener.com/c/F.2d/788/794/","op":1,"by":{"1":""}},{"t":"case","label":"Missouri Pac. R.R. v. United Transp. Union","cite":"782 F.2d 107","y":1986,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/782/107/","op":2,"by":{"1":""}},{"t":"case","label":"Bundy v. Penn Cent. Co.","cite":"455 F.2d 277","y":1972,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/455/277/","op":1,"by":{"1":""}},{"t":"case","label":"Nemitz v. Norfolk & W. Ry.","cite":"436 F.2d 841","url":"https://www.courtlistener.com/c/F.2d/436/841/","op":1,"by":{"1":""}},{"t":"case","label":"Pittston Coal Group v. Sebben","cite":"109 S. Ct. 414","y":1988,"id":"1988/87-821","sc":1,"sum":"The Black Lung Benefits Reform Act of 1977 (BLBRA), in 30 U. S. C. § 902(f)(2), provided that, pending the issuance of permanent regulations by the Secretary of Labor, cases filed or pending, as well as certain claims required to be reopened or readjudicated, were to be assessed under \"[c]riteria... not... more restrictive than the criteria applicable to a claim filed on June 30, 1973.\" As of that date, under …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":""}},{"t":"case","label":"Regan v. Wald","cite":"468 U.S. 222","y":1984,"id":"1983/83-436","sc":1,"sum":"Treasury Department Regulation 201(b), first promulgated in 1963 as part of the Cuban Assets Control Regulations, prohibits any transaction involving property in which Cuba, or any national thereof, has \"any interest of any nature whatsoever, direct or indirect.\" Regulation 560, which was added to the Regulations in 1977, embodied a general license permitting, for the most part, travel-related economic transactions …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":""}},{"t":"case","label":"Volkswagenwerk Aktiengesellschaft v. Federal Maritime Comm'n","cite":"390 U.S. 261","y":1968,"id":"1967/69","sc":1,"sum":"The Pacific Maritime Association (PMA), representing the Pacific Coast shipping industry employers, and the International Longshoremen's and Warehousemen's Union reached an agreement whereby the union consented to the use of labor-saving devices and the elimination of certain restrictive work practices in return for PMA's promise to create a $29,000,000 fund to mitigate the effect of technological unemployment. The …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":""}},{"t":"case","label":"McLean Trucking Co. v. United States","cite":"321 U.S. 67","y":1944,"id":"scdb/1943-115","sc":1,"by":{"1":""}},{"t":"case","label":"St. Joe Paper Co. v. Atlantic Coast Line R.R.","cite":"347 U.S. 298","y":1954,"id":"1940-1955/347us298","sc":1,"op":1,"sum":"The Interstate Commerce Commission does not have the power under § 77 of the Bankruptcy Act to initiate and submit to a district court a plan of reorganization whereby a debtor railroad would be compelled to merge with another railroad having no prior connection with the debtor.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":""}},{"t":"case","label":"Lehman v. Nakshian","cite":"453 U.S. 156","y":1981,"id":"1980/80-242","sc":1,"sum":"Respondent was not entitled to a jury trial.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":""}},{"t":"case","label":"Fedorenko v. United States","cite":"449 U.S. 490","y":1981,"id":"1980/79-5602","sc":1,"sum":"The Displaced Persons Act of 1948 (DPA) enabled European refugees driven from their homelands by World War II to emigrate to the United States without regard to traditional immigration quotas. It provided that any person \"who shall willfully make a misrepresentation for the purpose of gaining admission into the United States as an eligible displaced person shall thereafter not be admissible into the United States,\" …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":""}},{"t":"case","label":"United States v. Erika, Inc.","cite":"456 U.S. 201","y":1982,"id":"1981/80-1594","sc":1,"sum":"The Court of Claims has no jurisdiction to review determinations by private insurance carriers of the amount of benefits payable under Part B of the Medicare program.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":""}},{"t":"case","label":"Trailer Marine Transp. Corp. v. FMC","cite":"602 F.2d 379","url":"https://www.courtlistener.com/c/F.2d/602/379/","by":{"1":""}},{"t":"case","label":"Fox v. Standard Oil Co.","cite":"294 U.S. 87","y":1935,"id":"scdb/1934-085","sc":1,"sum":"1. Filling stations and distribution plants where gasoline, other petroleum products, and automobile accessories are sold, are \"stores \" within the meaning of the West Virginia Chain Store License Tax Act, defining the term store as including any mercantile establishment in which goods, wares or merchandise of any kind are sold, etc.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":""}},{"t":"case","label":"Texas v. United States","cite":"292 U.S. 522","y":1934,"id":"scdb/1933-045","sc":1,"op":1,"sum":"1. It is a primary aim in the new railroad policy inaugurated by the Transportation Act, 1920, to secure avoidance of waste; and the authority given to the Interstate Commerce Commission to permit consolidations, purchases, leases, etc., was given in aid of that policy.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":""}},{"t":"case","label":"Elgin, J. & E. Ry. v. Burley","cite":"325 U.S. 711","y":1945,"id":"scdb/1944-110","sc":1,"sum":"1. The contention that an award of the National Railroad Adjustment Board under the Railway Labor Act amounts to nothing more than an advisory opinion is inconsistent with the terms, purposes and legislative history of the Act and with decisions of this Court construing it.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":""}},{"t":"case","label":"Brotherhood of R.R. Trainmen v. Jacksonville Terminal Co.","cite":"394 U.S. 369","y":1969,"id":"1968/69","sc":1,"sum":"Florida East Coast Railway Co. (FEC), having exhausted all the Railway Labor Act's procedures for resolving a \"major dispute,\" unilaterally changed its operating employees' rates of pay, rules, and working conditions, and petitioner unions called a strike and picketed peacefully at locations where FEC operated, including the premises of respondent terminal company. A federal district court enjoined picketing of …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":""}},{"t":"case","label":"Louisiana v. New Orleans","cite":"102 U.S. 203","y":1880,"id":"scdb/1880-022","sc":1,"sum":"Morris Ranger recovered, May 1, 1874, against the city of New Orleans certain judgments. To enforce the collection of thém, he instituted, June 21, 1879, this proceeding, in the name of.the State on, his relation' in the Third District Court of the Parish of' Orleans,.for a peremptory mandamus to compel the mayor and administrators of the city to levy and collect a special tax sufficient in amount to satisfy the …","sumSrc":"Headnote (U.S. Reports)","by":{"1":""}},{"t":"case","label":"Texas & N. O. R.R. v. Brotherhood of R.R. Trainmen","cite":"307 F.2d 151","y":1962,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/307/151/","op":1,"sum":"Holding that the predecessor to Section 11341(a) does not preempt the Norris-LaGuardia Act, 29 U.S.C. 101 et seq., or a prior collective bargaining agreement, but recognizing that under the predecessor provision the Commission has jurisdiction \"to find whether certain of the union (contractual) demands are contrary to the public interest in the effectuation of the transaction\" and \"thereafter to prevent the enforcement\" of those demands.","sumSrc":"brief:1","by":{"1":""}},{"t":"case","label":"Burlington Northern, Inc. v. American Ry. Supervisors Ass'n","cite":"503 F.2d 58","y":1974,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/503/58/","op":1,"by":{"1":""}},{"t":"case","label":"Transamerica Mortgage Advisors, Inc. v. Lewis","cite":"444 U.S. 11","y":1979,"id":"1978/77-1645","sc":1,"sum":"Respondent, a shareholder of petitioner Mortgage Trust of America (Trust), brought this suit in Federal District Court as a derivative action on behalf of the Trust and as a class action on behalf of the Trust's shareholders, alleging that several trustees of the Trust, its investment adviser, and two corporations affiliated with the latter, had been guilty of various frauds and breaches of fiduciary duty in …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":""}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"1":""}},{"t":"usc","label":"49 U.S.C. § 11031","url":"https://www.law.cornell.edu/uscode/text/49/11031","by":{"1":""}},{"t":"usc","label":"49 U.S.C. § 11343","url":"https://www.law.cornell.edu/uscode/text/49/11343","subs":["(a)(1)"],"stext":{"head":"§11343. Consolidation, merger, and acquisition of control","paras":[[0,"(a) The following transactions involving carriers providing transportation subject to the jurisdiction of the Interstate Commerce Commission under subchapter I (except a pipeline carrier), II, or III of chapter 105 of this title may be carried out only with the approval and authorization of the Commission:"],[1,"(1) consolidation or merger of the properties or franchises of at least 2 carriers into one corporation for the ownership, management, and operation of the previously separately owned properties."],[1,"(2) a purchase, lease, or contract to operate property of another carrier by any number of carriers."],[1,"(3) acquisition of control of a carrier by any number of carriers."],[1,"(4) acquisition of control of at least 2 carriers by a person that is not a carrier."],[1,"(5) acquisition of control of a carrier by a person that is not a carrier but that controls any number of carriers."],[1,"(6) acquisition by a rail carrier of trackage rights over, or joint ownership in or joint use of, a railroad line (and terminals incidental to it) owned or operated by another rail carrier."],[0,"(b) A person may carry out a transaction referred to in subsection (a) of this section or participate in achieving the control or management, including the power to exercise control or management, in a common interest of more than one of those carriers, regardless of how that result is reached, only with the approval and authorization of the Commission under this subchapter. In addition to other transactions, each of the following transactions are considered achievements of control or management:"],[1,"(1) A transaction by a carrier has the effect of putting that carrier and persons affiliated with it, taken together, in control of another carrier."],[1,"(2) A transaction by a person affiliated with a carrier has the effect of putting that carrier and persons affiliated with it, taken together, in control of another carrier."],[1,"(3) A transaction by at least 2 persons acting together (one of whom is a carrier or is affiliated with a carrier) has the effect of putting those persons and carriers and persons affiliated with any of them, or with any of those affiliated carriers, taken together, in control of another carrier."],[0,"(c) A person is affiliated with a carrier under this subchapter if, because of the relationship between that person and a carrier, it is reasonable to believe that the affairs of another carrier, control of which may be acquired by that person, will be managed in the interest of the other carrier."],[0,"(d)(1) Approval and authorization by the Commission are not required if the only parties to a transaction referred to in subsection (a) of this section are motor carriers providing transportation subject to the jurisdiction of the Commission under subchapter II of chapter 105 of this title and the aggregate gross operating revenues of those carriers were not more than $2,000,000 during a period of 12 consecutive months ending not more than 6 months before the date of the agreement of the parties covering the transaction. However, the approval and authorization of the Commission is required when a motor carrier that is controlled by or affiliated with a carrier providing transportation subject to the jurisdiction of the Commission under subchapter I of that chapter is a party to the transaction."],[0,"(2) The approval and authorization of the Commission are not required if the only parties to a transaction referred to in subsection (a) of this section are street, suburban, or interurban electric railways that are not controlled by or under common control with a carrier that is operated as part of a general railroad system of transportation."],[0,"(e)(1) Notwithstanding any provisions of this title, the Interstate Commerce Commission, in a matter related to a motor carrier of property providing transportation subject to the jurisdiction of the Commission under subchapter II of chapter 105 of this title, may exempt a person, class of persons, transaction, or class of transactions from the merger, consolidation, and acquisition of control provisions of this subchapter if the Commission finds that—"],[1,"(A) the application of such provisions is not necessary to carry out the transportation policy of section 10101 of this title; and"],[1,"(B) either (i) the transaction is of limited scope, or (ii) the application of such provisions is not needed to protect shippers from the abuse of market power."],[0,"(2) At least 60 days before any transaction exempt under this subsection from the merger, consolidation, and acquisition of control provisions of this subchapter may take effect, each carrier intending to participate in such transaction shall file with the Commission a notice of its intention to participate in such transaction and shall give public notice of such intention. The Commission shall prescribe the information to be contained in such notices, including the nature and scope of the transaction."],[0,"(3) The Commission, on its own initiative or on complaint, may revoke an exemption granted under this subsection, to the extent it specifies, when it finds that application of the provisions of this section to the person, class of persons, or transportation is necessary to carry out the transportation policy of section 10101 of this title."],[0,"(4) If the Commission, on its own initiative, finds that employees of any carrier intending to participate in a transaction exempt under this subsection from the merger, consolidation, and acquisition of control provisions of this subchapter are or will be adversely affected by such transaction or if employees of such carrier adversely affected by such transaction file a complaint concerning such transaction with the Commission, the Commission shall revoke such exemption to the extent the Commission deems necessary to review and address the adverse effects on such employees."]],"more":false,"ed":"1994","src":"https://www.govinfo.gov/link/uscode/49/11343?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§11343. Consolidation, merger, and acquisition of control","tname":"Transportation","by":{"1":""}},{"t":"usc","label":"45 U.S.C. § 152","url":"https://www.law.cornell.edu/uscode/text/45/152","stext":{"head":"§152. General duties","paras":[[0,"First. Duty of carriers and employees to settle disputes"],[0,"It shall be the duty of all carriers, their officers, agents, and employees to exert every reasonable effort to make and maintain agreements concerning rates of pay, rules, and working conditions, and to settle all disputes, whether arising out of the application of such agreements or otherwise, in order to avoid any interruption to commerce or to the operation of any carrier growing out of any dispute between the carrier and the employees thereof."],[0,"Second. Consideration of disputes by representatives"],[0,"All disputes between a carrier or carriers and its or their employees shall be considered, and, if possible, decided, with all expedition, in conference between representatives designated and authorized so to confer, respectively, by the carrier or carriers and by the employees thereof interested in the dispute."],[0,"Third. Designation of representatives"],[0,"Representatives, for the purposes of this chapter, shall be designated by the respective parties without interference, influence, or coercion by either party over the designation of representatives by the other; and neither party shall in any way interfere with, influence, or coerce the other in its choice of representatives. Representatives of employees for the purposes of this chapter need not be persons in the employ of the carrier, and no carrier shall, by interference, influence, or coercion seek in any manner to prevent the designation by its employees as their representatives of those who or which are not employees of the carrier."],[0,"Fourth. Organization and collective bargaining; freedom from interference by carrier; assistance in organizing or maintaining organization by carrier forbidden; deduction of dues from wages forbidden"],[0,"Employees shall have the right to organize and bargain collectively through representatives of their own choosing. The majority of any craft or class of employees shall have the right to determine who shall be the representative of the craft or class for the purposes of this chapter. No carrier, its officers, or agents shall deny or in any way question the right of its employees to join, organize, or assist in organizing the labor organization of their choice, and it shall be unlawful for any carrier to interfere in any way with the organization of its employees, or to use the funds of the carrier in maintaining or assisting or contributing to any labor organization, labor representative, or other agency of collective bargaining, or in performing any work therefor, or to influence or coerce employees in an effort to induce them to join or remain or not to join or remain members of any labor organization, or to deduct from the wages of employees any dues, fees, assessments, or other contributions payable to labor organizations, or to collect or to assist in the collection of any such dues, fees, assessments, or other contributions: Provided, That nothing in this chapter shall be construed to prohibit a carrier from permitting an employee, individually, or local representatives of employees from conferring with management during working hours without loss of time, or to prohibit a carrier from furnishing free transportation to its employees while engaged in the business of a labor organization."],[0,"Fifth. Agreements to join or not to join labor organizations forbidden"],[0,"No carrier, its officers, or agents shall require any person seeking employment to sign any contract or agreement promising to join or not to join a labor organization; and if any such contract has been enforced prior to the effective date of this chapter, then such carrier shall notify the employees by an appropriate order that such contract has been discarded and is no longer binding on them in any way."],[0,"Sixth. Conference of representatives; time; place; private agreements"],[0,"In case of a dispute between a carrier or carriers and its or their employees, arising out of grievances or out of the interpretation or application of agreements concerning rates of pay, rules, or working conditions, it shall be the duty of the designated representative or representatives of such carrier or carriers and of such employees, within ten days after the receipt of notice of a desire on the part of either party to confer in respect to such dispute, to specify a time and place at which such conference shall be held: Provided, (1) That the place so specified shall be situated upon the line of the carrier involved or as otherwise mutually agreed upon; and (2) that the time so specified shall allow the designated conferees reasonable opportunity to reach such place of conference, but shall not exceed twenty days from the receipt of such notice: And provided further, That nothing in this chapter shall be construed to supersede the provisions of any agreement (as to conferences) then in effect between the parties."],[0,"Seventh. Change in pay, rules, or working conditions contrary to agreement or to section 156 forbidden"],[0,"No carrier, its officers, or agents shall change the rates of pay, rules, or working conditions of its employees, as a class, as embodied in agreements except in the manner prescribed in such agreements or in section 156 of this title."],[0,"Eighth. Notices of manner of settlement of disputes; posting"],[0,"Every carrier shall notify its employees by printed notices in such form and posted at such times and places as shall be specified by the Mediation Board that all disputes between the carrier and its employees will be handled in accordance with the requirements of this chapter, and in such notices there shall be printed verbatim, in large type, the third, fourth, and fifth paragraphs of this section. The provisions of said paragraphs are made a part of the contract of employment between the carrier and each employee, and shall be held binding upon the parties, regardless of any other express or implied agreements between them."],[0,"Ninth. Disputes as to identity of representatives; designation by Mediation Board; secret elections"],[0,"If any dispute shall arise among a carrier's employees as to who are the representatives of such employees designated and authorized in accordance with the requirements of this chapter, it shall be the duty of the Mediation Board, upon request of either party to the dispute, to investigate such dispute and to certify to both parties, in writing, within thirty days after the receipt of the invocation of its services, the name or names of the individuals or organizations that have been designated and authorized to represent the employees involved in the dispute, and certify the same to the carrier. Upon receipt of such certification the carrier shall treat with the representative so certified as the representative of the craft or class for the purposes of this chapter. In such an investigation, the Mediation Board shall be authorized to take a secret ballot of the employees involved, or to utilize any other appropriate method of ascertaining the names of their duly designated and authorized representatives in such manner as shall insure the choice of representatives by the employees without interference, influence, or coercion exercised by the carrier. In the conduct of any election for the purposes herein indicated the Board shall designate who may participate in the election and establish the rules to govern the election, or may appoint a committee of three neutral persons who after hearing shall within ten days designate the employees who may participate in the election. In any such election for which there are 3 or more options (including the option of not being represented by any labor organization) on the ballot and no such option receives a majority of the valid votes cast, the Mediation Board shall arrange for a second election between the options receiving the largest and the second largest number of votes. The Board shall have access to and have power to make copies of the books and records of the carriers to obtain and utilize such information as may be deemed necessary by it to carry out the purposes and provisions of this paragraph."],[0,"Tenth. Violations; prosecution and penalties"],[0,"The willful failure or refusal of any carrier, its officers or agents, to comply with the terms of the third, fourth, fifth, seventh, or eighth paragraph of this section shall be a misdemeanor, and upon conviction thereof the carrier, officer, or agent offending shall be subject to a fine of not less than $1,000, nor more than $20,000, or imprisonment for not more than six months, or both fine and imprisonment, for each offense, and each day during which such carrier, officer, or agent shall willfully fail or refuse to comply with the terms of the said paragraphs of this section shall constitute a separate offense. It shall be the duty of any United States attorney to whom any duly designated representative of a carrier's employees may apply to institute in the proper court and to prosecute under the direction of the Attorney General of the United States, all necessary proceedings for the enforcement of the provisions of this section, and for the punishment of all violations thereof and the costs and expenses of such prosecution shall be paid out of the appropriation for the expenses of the courts of the United States: Provided, That nothing in this chapter shall be construed to require an individual employee to render labor or service without his consent, nor shall anything in this chapter be construed to make the quitting of his labor by an individual employee an illegal act; nor shall any court issue any process to compel the performance by an individual employee of such labor or service, without his consent."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/45/152?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§152. General duties","tname":"Railroads","by":{"1":""}},{"t":"usc","label":"28 U.S.C. § 2342","url":"https://www.law.cornell.edu/uscode/text/28/2342","by":{"1":""}},{"t":"usc","label":"28 U.S.C. § 2341","url":"https://www.law.cornell.edu/uscode/text/28/2341","by":{"1":""}},{"t":"usc","label":"28 U.S.C. § 2350","url":"https://www.law.cornell.edu/uscode/text/28/2350","by":{"1":""}},{"t":"usc","label":"45 U.S.C. § 156","url":"https://www.law.cornell.edu/uscode/text/45/156","by":{"1":""}},{"t":"usc","label":"29 U.S.C. § 101","url":"https://www.law.cornell.edu/uscode/text/29/101","by":{"1":""}}]};